def frontier_joint_intervals(
    reports: dict,
    weights: dict,
    cost: dict,
    limits: list,
    cases: dict,
    *,
    alpha: float = 0.05,
) -> str:
    """Merge adjacent frontier_joint limits sharing a modal pick.

    ``reports``, ``weights``, ``cost``, ``limits``, ``cases`` and ``alpha``
    follow the :func:`frontier_joint` contract exactly: the same parameter
    types, the same ``TypeError``/``ValueError`` split and the same
    per-case, per-limit winning subset computation — for each case the
    effective cost of a candidate is its ``cost`` times the case cost
    multiplier, its effective gain is the panel ``score`` times the case
    gain multiplier, and at each limit the winner over all subsets of the
    significant candidates with total effective cost at most the limit
    maximizes total gain, then minimizes total cost, then minimizes the
    lexicographically ascending selected-key list.

    Limits are processed in ascending numeric order. At each limit the
    winning picks of every case vote: the point's modal pick is the most
    frequent winning pick with ties broken by the lexicographically
    ascending selected-key list. Adjacent limits whose modal picks are
    equal are merged into one interval. For each interval ``start`` and
    ``end`` are the first and last limit it spans, ``threshold`` is
    ``null`` for the first interval and the interval's ``start`` for every
    later one, ``n`` is the number of limits merged into it and
    ``stability`` is the minimum over its limits of the modal pick's
    frequency divided by the number of cases. For each case ``cost`` and
    ``gain`` are the means of its winning subset's total effective cost
    and total effective gain over the interval's limits and ``support``
    is the share of the interval's limits where the case's winning pick
    equals the interval's modal pick. ``worst`` is the key of the case
    with the minimum ``gain``, ties broken by the ascending case key. All
    arithmetic is ``Decimal(str(x))`` under a precision-1000,
    ROUND_HALF_EVEN context and comparisons use the unquantized values.

    Returns a compact UTF-8 JSON string with no spaces and exactly one
    trailing newline; the top-level key order is ``alpha, intervals``.
    Each interval uses the key order ``start, end, threshold, pick, n,
    stability, worst, cases`` and each case entry the key order ``key,
    cost, gain, support``; intervals are sorted by ascending ``start``
    and case entries by ascending ``key``. ``pick`` is an ascending
    string array, ``n`` is an integer, ``worst`` and ``key`` are strings,
    ``threshold`` is ``null`` or a number and every numeric value renders
    with six decimals, negative zero normalized to ``0.000000``.
    """
    if not isinstance(reports, dict):
        raise TypeError("reports must be a dict")
    if not isinstance(weights, dict):
        raise TypeError("weights must be a dict")
    if not isinstance(cost, dict):
        raise TypeError("cost must be a dict")
    if not isinstance(limits, list):
        raise TypeError("limits must be a list")
    if not isinstance(cases, dict):
        raise TypeError("cases must be a dict")
    if not limits:
        raise ValueError("limits must be a non-empty list")
    if not cases:
        raise ValueError("cases must be a non-empty dict")

    alpha_value, _groups_spec, records = _panel_report_data(
        reports, weights, alpha
    )

    overall_mean: dict[str, Decimal] = {}
    min_stable: dict[str, Decimal] = {}
    significant: dict[str, bool] = {}
    for by, _group_key, candidate, _n, mean, _range, stable, _p, q in records:
        if candidate not in min_stable or stable < min_stable[candidate]:
            min_stable[candidate] = stable
        if by == "overall":
            overall_mean[candidate] = mean
        reject = q <= alpha_value
        if candidate in significant:
            significant[candidate] = significant[candidate] and reject
        else:
            significant[candidate] = reject

    candidates = sorted(overall_mean)
    if set(cost) != set(candidates):
        raise ValueError("cost keys must be exactly the candidate keys")
    costs: dict[str, Decimal] = {}
    for key in candidates:
        cost_value = _portfolio_number(cost[key], "cost")
        if cost_value <= 0:
            raise ValueError("each cost must be positive")
        costs[key] = cost_value

    limit_values: list[Decimal] = []
    seen_limits: set[Decimal] = set()
    for limit in limits:
        limit_value = _portfolio_number(limit, "limits")
        if limit_value < 0:
            raise ValueError("each limit must be non-negative")
        if limit_value in seen_limits:
            raise ValueError("limits must be distinct")
        seen_limits.add(limit_value)
        limit_values.append(limit_value)
    limit_values.sort()

    case_keys: list[str] = []
    cost_multipliers: dict[str, dict[str, Decimal]] = {}
    gain_multipliers: dict[str, dict[str, Decimal]] = {}
    for case_key, mapping in cases.items():
        if not isinstance(case_key, str) or not case_key:
            raise ValueError("each cases key must be a non-empty string")
        if not isinstance(mapping, dict):
            raise TypeError("each cases value must be a dict")
        if set(mapping) != {"cost", "gain"}:
            raise ValueError(
                'each cases value must contain exactly the keys "cost" '
                'and "gain"'
            )
        case_costs = mapping["cost"]
        case_gains = mapping["gain"]
        if not isinstance(case_costs, dict) or not isinstance(
            case_gains, dict
        ):
            raise TypeError(
                "each cases cost and gain value must be a dict"
            )
        if set(case_costs) != set(candidates) or set(case_gains) != set(
            candidates
        ):
            raise ValueError(
                "each cases cost and gain dict must be keyed by exactly "
                "the candidate keys"
            )
        case_cost_multipliers: dict[str, Decimal] = {}
        case_gain_multipliers: dict[str, Decimal] = {}
        for key in candidates:
            multiplier = _portfolio_number(
                case_costs[key], "cost multiplier"
            )
            if multiplier <= 0:
                raise ValueError("each cost multiplier must be positive")
            case_cost_multipliers[key] = multiplier
            multiplier = _portfolio_number(
                case_gains[key], "gain multiplier"
            )
            if multiplier <= 0:
                raise ValueError("each gain multiplier must be positive")
            case_gain_multipliers[key] = multiplier
        case_keys.append(case_key)
        cost_multipliers[case_key] = case_cost_multipliers
        gain_multipliers[case_key] = case_gain_multipliers
    case_keys.sort()

    with localcontext() as ctx:
        ctx.prec = _MODEL_PRECISION
        ctx.rounding = ROUND_HALF_EVEN

        scores = {
            key: overall_mean[key] * min_stable[key] for key in candidates
        }
        sig_keys = [key for key in candidates if significant[key]]
        sig_count = len(sig_keys)

        # case key -> per-limit winning (gain, cost, keys) triples
        case_winners: dict[
            str, list[tuple[Decimal, Decimal, tuple[str, ...]]]
        ] = {}
        for case_key in case_keys:
            case_costs = {
                key: costs[key] * cost_multipliers[case_key][key]
                for key in sig_keys
            }
            case_gains = {
                key: scores[key] * gain_multipliers[case_key][key]
                for key in sig_keys
            }
            subsets: list[tuple[Decimal, Decimal, tuple[str, ...]]] = []
            for size in range(sig_count + 1):
                for idxs in combinations(range(sig_count), size):
                    total_cost = sum(
                        (case_costs[sig_keys[i]] for i in idxs), Decimal(0)
                    )
                    total_gain = sum(
                        (case_gains[sig_keys[i]] for i in idxs), Decimal(0)
                    )
                    subsets.append(
                        (
                            total_gain,
                            total_cost,
                            tuple(sig_keys[i] for i in idxs),
                        )
                    )
            winners: list[tuple[Decimal, Decimal, tuple[str, ...]]] = []
            for limit_value in limit_values:
                best: tuple[Decimal, Decimal, tuple[str, ...]] | None = None
                for total_gain, total_cost, chosen_keys in subsets:
                    if total_cost > limit_value:
                        continue
                    if (
                        best is None
                        or total_gain > best[0]
                        or (
                            total_gain == best[0]
                            and (
                                total_cost < best[1]
                                or (
                                    total_cost == best[1]
                                    and chosen_keys < best[2]
                                )
                            )
                        )
                    ):
                        best = (total_gain, total_cost, chosen_keys)
                assert best is not None  # the empty subset is always feasible
                winners.append(best)
            case_winners[case_key] = winners

        case_total = len(case_keys)

        # per-limit modal pick and its frequency share
        point_modals: list[tuple[str, ...]] = []
        point_stability: list[Decimal] = []
        for limit_index in range(len(limit_values)):
            pick_counts: dict[tuple[str, ...], int] = {}
            for case_key in case_keys:
                pick = case_winners[case_key][limit_index][2]
                pick_counts[pick] = pick_counts.get(pick, 0) + 1
            modal_frequency = max(pick_counts.values())
            modal_pick = min(
                pick
                for pick, frequency in pick_counts.items()
                if frequency == modal_frequency
            )
            point_modals.append(modal_pick)
            point_stability.append(
                Decimal(modal_frequency) / Decimal(case_total)
            )

        # merge adjacent limits sharing the modal pick
        segments: list[tuple[int, int]] = []
        segment_start = 0
        for limit_index in range(1, len(limit_values)):
            if point_modals[limit_index] != point_modals[segment_start]:
                segments.append((segment_start, limit_index - 1))
                segment_start = limit_index
        segments.append((segment_start, len(limit_values) - 1))

        interval_strings: list[str] = []
        for segment_index, (first, last) in enumerate(segments):
            n = last - first + 1
            modal_pick = point_modals[first]
            stability = min(point_stability[first:last + 1])
            if segment_index == 0:
                threshold = "null"
            else:
                threshold = _format6(limit_values[first])

            case_strings: list[str] = []
            worst_key: str | None = None
            worst_gain: Decimal | None = None
            for case_key in case_keys:
                mean_cost = sum(
                    (case_winners[case_key][i][1]
                     for i in range(first, last + 1)),
                    Decimal(0),
                ) / Decimal(n)
                mean_gain = sum(
                    (case_winners[case_key][i][0]
                     for i in range(first, last + 1)),
                    Decimal(0),
                ) / Decimal(n)
                support_count = sum(
                    1
                    for i in range(first, last + 1)
                    if case_winners[case_key][i][2] == modal_pick
                )
                support = Decimal(support_count) / Decimal(n)
                if worst_gain is None or mean_gain < worst_gain:
                    worst_gain = mean_gain
                    worst_key = case_key
                case_strings.append(
                    '{"key":' + json.dumps(case_key, ensure_ascii=False)
                    + ',"cost":' + _format6(mean_cost)
                    + ',"gain":' + _format6(mean_gain)
                    + ',"support":' + _format6(support)
                    + "}"
                )
            assert worst_key is not None  # cases is non-empty

            interval_strings.append(
                '{"start":' + _format6(limit_values[first])
                + ',"end":' + _format6(limit_values[last])
                + ',"threshold":' + threshold
                + ',"pick":'
                + json.dumps(
                    list(modal_pick),
                    ensure_ascii=False,
                    separators=(",", ":"),
                )
                + ',"n":' + str(n)

def _scenario_decision_inputs(
    reports: dict, weights: dict
) -> tuple | None:
    """Validate and parse the shared ``scenario_decision*`` inputs.

    Performs every input check of :func:`scenario_decision` and
    returns ``None`` when ``reports`` is empty (the only valid empty
    case); otherwise returns ``(weight_values, panels, scenario_keys,
    kind_values, share_values)`` with ``weight_values`` the per-panel
    ``Decimal`` weights, ``panels`` mapping each ``(region, window)``
    panel key to ``{"ranks": key -> (kind, share, score, rank,
    stable), "pairs": [(a, b, diff, reject), ...]}`` and
    ``kind_values``/``share_values`` the per-scenario values that are
    required to agree across all panels.
    """
    if not isinstance(reports, dict):
        raise TypeError("reports must be a dict")
    if not isinstance(weights, dict):
        raise TypeError("weights must be a dict")
    for panel_key in reports:
        if (
            not isinstance(panel_key, tuple)
            or len(panel_key) != 2
            or not isinstance(panel_key[0], str)
            or not panel_key[0]
            or not isinstance(panel_key[1], str)
            or not panel_key[1]
        ):
            raise ValueError(
                "each reports key must be a (region, window) tuple of two "
                "non-empty strings"
            )
    if set(weights) != set(reports):
        raise ValueError("weights keys must be exactly the reports keys")
    if not reports:
        return None

    weight_values: dict[tuple[str, str], Decimal] = {}
    for panel_key, weight in weights.items():
        if isinstance(weight, bool) or not isinstance(weight, (int, float)):
            raise ValueError("each weight must be a finite int or float")
        if isinstance(weight, float) and not math.isfinite(weight):
            raise ValueError("each weight must be finite")
        decimal_weight = Decimal(str(weight))
        if decimal_weight <= 0:
            raise ValueError("each weight must be positive")
        weight_values[panel_key] = decimal_weight

    # panel key -> {"ranks": scenario key -> (kind, share, score, rank,
    # stable), "pairs": [(a, b, diff, reject), ...]}
    panels: dict[tuple[str, str], dict] = {}
    scenario_keys: set[str] | None = None
    for panel_key in sorted(reports):
        raw = reports[panel_key]
        if not isinstance(raw, str):
            raise ValueError(
                "each reports value must be a scenario_sensitivity JSON "
                "output"
            )
        try:
            data = json.loads(
                raw,
                parse_float=Decimal,
                parse_int=Decimal,
                parse_constant=_scenario_decision_parse_constant,
            )
        except ValueError:
            raise ValueError(
                "each reports value must be a scenario_sensitivity JSON "
                "output"
            ) from None
        if not isinstance(data, dict) or set(data) != {"ranks", "pairs"}:
            raise ValueError(
                "each reports value must be a scenario_sensitivity JSON "
                "output"
            )
        ranks_raw = data["ranks"]
        pairs_raw = data["pairs"]
        if not isinstance(ranks_raw, list) or not isinstance(pairs_raw, list):
            raise ValueError(
                "each reports value must be a scenario_sensitivity JSON "
                "output"
            )

        rank_map: dict[str, tuple] = {}
        for item in ranks_raw:
            if not isinstance(item, dict) or set(item) != {
                "key", "kind", "share", "score", "rank", "stable",
            }:
                raise ValueError(
                    "each reports value must be a scenario_sensitivity JSON "
                    "output"
                )
            key = item["key"]
            kind = item["kind"]
            share = item["share"]
            score = item["score"]
            rank = item["rank"]
            stable = item["stable"]
            if not isinstance(key, str) or not key:
                raise ValueError(
                    "each reports value must be a scenario_sensitivity JSON "
                    "output"
                )
            if (
                not isinstance(kind, str)
                or kind not in _SCENARIO_SENSITIVITY_KINDS
            ):
                raise ValueError(
                    "each reports value must be a scenario_sensitivity JSON "
                    "output"
                )
            if (
                not isinstance(share, Decimal)
                or not share.is_finite()
                or share <= 0
                or share > 1
            ):
                raise ValueError(
                    "each reports value must be a scenario_sensitivity JSON "
                    "output"
                )
            if not isinstance(score, Decimal) or not score.is_finite():
                raise ValueError(
                    "each reports value must be a scenario_sensitivity JSON "
                    "output"
                )
            if (
                not isinstance(rank, Decimal)
                or not rank.is_finite()
                or rank != rank.to_integral_value()
                or rank < 1
            ):
                raise ValueError(
                    "each reports value must be a scenario_sensitivity JSON "
                    "output"
                )
            if not isinstance(stable, bool):
                raise ValueError(
                    "each reports value must be a scenario_sensitivity JSON "
                    "output"
                )
            if key in rank_map:
                raise ValueError(
                    "each reports value must be a scenario_sensitivity JSON "
                    "output"
                )
            rank_map[key] = (kind, share, score, rank, stable)

        pair_list: list[tuple] = []
        for item in pairs_raw:
            if not isinstance(item, dict) or set(item) != {
                "a", "b", "diff", "p", "q", "reject",
            }:
                raise ValueError(
                    "each reports value must be a scenario_sensitivity JSON "
                    "output"
                )
            key_a = item["a"]
            key_b = item["b"]
            diff = item["diff"]
            p_value = item["p"]
            q_value = item["q"]
            reject = item["reject"]
            if (
                not isinstance(key_a, str)
                or not key_a
                or not isinstance(key_b, str)
                or not key_b
            ):
                raise ValueError(
                    "each reports value must be a scenario_sensitivity JSON "
                    "output"
                )
            for number in (diff, p_value, q_value):
                if not isinstance(number, Decimal) or not number.is_finite():
                    raise ValueError(
                        "each reports value must be a scenario_sensitivity "
                        "JSON output"
                    )
            if not isinstance(reject, bool):
                raise ValueError(
                    "each reports value must be a scenario_sensitivity JSON "
                    "output"
                )
            pair_list.append((key_a, key_b, diff, reject))

        if len(rank_map) < 2:
            raise ValueError(
                "each report must rank at least two scenarios"
            )
        if scenario_keys is None:
            scenario_keys = set(rank_map)
        elif set(rank_map) != scenario_keys:
            raise ValueError(
                "all reports must rank the same scenario keys"
            )
        panels[panel_key] = {"ranks": rank_map, "pairs": pair_list}

    # A scenario's kind and share must agree across every panel.

def _portfolio_number(value: object, name: str) -> Decimal:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{name} must be a finite int or float")
    if isinstance(value, float) and not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    return Decimal(str(value))


def portfolio(
    report: str, cost: dict, gain: dict, limit: float, rules: dict
) -> str:
    """Select the best candidate subset from a consensus report.

    ``report`` must be a :func:`decision_priority_consensus` JSON output;
    ``cost`` and ``gain`` are dicts whose key sets are exactly the
    report's candidate keys, with finite non-boolean int/float values
    (strictly positive costs, non-negative gains); ``limit`` is a
    non-negative finite non-boolean int/float; and ``rules`` has exactly
    the keys ``"mutex"`` and ``"requires"``, each a list of two-tuples of
    distinct candidate keys. Mutex pairs are undirected and
    deduplicated; a ``requires`` pair ``(a, b)`` means selecting ``a``
    forces ``b`` to be selected and pairs are deduplicated in order. A
    non-string ``report`` or a non-dict ``cost``, ``gain`` or ``rules``
    raises ``TypeError``; every other contract violation raises
    ``ValueError``.

input.new_string:
    return (
        '{"alpha":' + _format6(alpha_value)
        + ',"intervals":[' + ",".join(interval_strings) + "]}\n"
    )


_INTERVAL_ATTRIBUTION_ERROR = (
    "each reports value must be a frontier_joint_intervals JSON output"
)
_INTERVAL_ATTRIBUTION_INT_RE = re.compile(r"(?:0|[1-9][0-9]*)")
_INTERVAL_ATTRIBUTION_DECIMAL_RE = re.compile(
    r"-?(?:0|[1-9][0-9]*)\.[0-9]{6}"
)


class _IntervalAttributionInt(Decimal):
    """Marker for a canonical unsigned JSON integer token."""


class _IntervalAttributionDecimal(Decimal):
    """Marker for a canonical fixed-six-decimal JSON number token."""


def _interval_attribution_parse_constant(value: str) -> Decimal:
    raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)


def _interval_attribution_signed_zero(value: Decimal) -> bool:
    return value == 0 and value.is_signed()


def _frontier_interval_report(raw: object) -> dict:
    """Parse one canonical :func:`frontier_joint_intervals` JSON output.

    Returns ``{"alpha": Decimal, "intervals": [interval, ...]}`` with each
    interval a dict carrying ``start``/``end`` ``Decimal`` values,
    ``pick`` a tuple of strings, and ``cases`` a list of
    ``(key, gain)`` pairs in the report's case order. The input must be
    byte-for-byte identical to a canonical output (key order, escaping,
    spacing, the integer ``n`` token, the ``null`` threshold and the
    six-decimal numeric tokens included); any deviation raises
    ``ValueError``.
    """
    if not isinstance(raw, str):
        raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
    if not raw.endswith("\n") or raw.endswith("\n\n"):
        raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
    payload = raw[:-1]

    def _parse_integer(value: str) -> Decimal:
        if not _INTERVAL_ATTRIBUTION_INT_RE.fullmatch(value):
            raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
        return _IntervalAttributionInt(value)

    def _parse_decimal(value: str) -> Decimal:
        if not _INTERVAL_ATTRIBUTION_DECIMAL_RE.fullmatch(value):
            raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
        return _IntervalAttributionDecimal(value)

    try:
        data = json.loads(
            payload,
            parse_float=_parse_decimal,
            parse_int=_parse_integer,
            parse_constant=_interval_attribution_parse_constant,
        )
    except ValueError:
        raise ValueError(_INTERVAL_ATTRIBUTION_ERROR) from None
    if not isinstance(data, dict) or set(data) != {"alpha", "intervals"}:
        raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
    alpha_raw = data["alpha"]
    intervals_raw = data["intervals"]
    if not isinstance(alpha_raw, _IntervalAttributionDecimal) or not isinstance(
        intervals_raw, list
    ):
        raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
    # Canonical alpha is in (0, 1] and never a negative zero.
    if alpha_raw <= 0 or alpha_raw > 1 or (
        alpha_raw == 0 and alpha_raw.is_signed()
    ):
        raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)

    intervals: list[dict] = []
    interval_tokens: list[str] = []
    last_end: Decimal | None = None
    for index, interval in enumerate(intervals_raw):
        if not isinstance(interval, dict) or set(interval) != {
            "start", "end", "threshold", "pick", "n",
            "stability", "worst", "cases",
        }:
            raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
        start = interval["start"]
        end = interval["end"]
        threshold = interval["threshold"]
        pick = interval["pick"]
        n_value = interval["n"]
        stability = interval["stability"]
        worst = interval["worst"]
        cases = interval["cases"]
        if not isinstance(start, _IntervalAttributionDecimal) or not isinstance(
            end, _IntervalAttributionDecimal
        ):
            raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
        # threshold is null for the first interval and the start token for
        # every later one.
        if index == 0:
            if threshold is not None:
                raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
            threshold_token = "null"
        else:
            if not isinstance(threshold, _IntervalAttributionDecimal) or (
                threshold != start
            ):
                raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
            threshold_token = str(threshold)
        if not isinstance(pick, list) or any(
            not isinstance(key, str) for key in pick
        ):
            raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
        if any(pick[i] >= pick[i + 1] for i in range(len(pick) - 1)):
            raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
        if not isinstance(n_value, _IntervalAttributionInt) or n_value < 1:
            raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
        if not isinstance(stability, _IntervalAttributionDecimal):
            raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
        if not isinstance(worst, str) or not worst:
            raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
        if not isinstance(cases, list) or not cases:
            raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
        # Intervals are sorted by ascending, non-overlapping start/end.
        if (
            start > end
            or (last_end is not None and start <= last_end)
            or _interval_attribution_signed_zero(start)
            or _interval_attribution_signed_zero(end)
        ):
            raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
        if stability < 0 or stability > 1 or (
            _interval_attribution_signed_zero(stability)
        ):
            raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)

        case_pairs: list[tuple[str, Decimal]] = []
        case_tokens: list[str] = []
        last_case_key: str | None = None
        for case in cases:
            if not isinstance(case, dict) or set(case) != {
                "key", "cost", "gain", "support",
            }:
                raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
            case_key = case["key"]
            cost = case["cost"]
            gain = case["gain"]
            support = case["support"]
            if (
                not isinstance(case_key, str)
                or not case_key
                or not isinstance(cost, _IntervalAttributionDecimal)
                or not isinstance(gain, _IntervalAttributionDecimal)
                or not isinstance(support, _IntervalAttributionDecimal)
            ):
                raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
            if cost < 0 or support < 0 or support > 1:
                raise ValueError(_INTERVAL_ATTRIBUTION_ERROR)
