                + ',"region":' + json.dumps(region, ensure_ascii=False)
                + ',"window":' + json.dumps(window, ensure_ascii=False)
                + ',"factors":{"weather":'
                + _format6(factor_values["weather"])
                + ',"cover":' + _format6(factor_values["cover"])
                + ',"morphology":'
                + _format6(factor_values["morphology"])
                + "}}"
            )

